package decode

import (
	"bytes"
	"github.com/chaim12345/sdrstream/go/internal/testutil/sstvfixture"
	"image"
	"image/png"
	"strings"
	"testing"
)

// The fixtures in testdata/ are generated by tools/gen_sstv_fixtures.py
// with the independent pysstv encoder (plus numpy clock-offset and AWGN
// channel impairments), so these tests share no constants with the
// decoder. The encoded pattern is five vertical bars (red, green, blue,
// white, black) on the top half and a horizontal luminance ramp with a
// white square on the bottom half.

func readSSTVFixture(t *testing.T, name string) ([]float64, int) {
	t.Helper()
	samples, rate, err := ReadWAV("testdata/" + name + ".wav")
	if err != nil {
		t.Fatalf("ReadWAV %s: %v", name, err)
	}
	return samples, rate
}

func decodeFixture(t *testing.T, name string) image.Image {
	t.Helper()
	samples, rate := readSSTVFixture(t, name)
	pngBytes, err := SSTVImage(samples, rate)
	if err != nil {
		t.Fatalf("SSTVImage %s: %v", name, err)
	}
	img, err := png.Decode(bytes.NewReader(pngBytes))
	if err != nil {
		t.Fatalf("png.Decode %s: %v", name, err)
	}
	return img
}

func chanVal(img image.Image, x, y int) (int, int, int) {
	r, g, b, _ := img.At(x, y).RGBA()
	return int(r >> 8), int(g >> 8), int(b >> 8)
}

func near(t *testing.T, what string, got, want, tol int) {
	t.Helper()
	if got < want-tol || got > want+tol {
		t.Errorf("%s = %d, want %d +/- %d", what, got, want, tol)
	}
}

// checkPattern verifies the decoded image against the known fixture
// pattern: bar colours at one quarter height, a monotonic ramp at 60%
// height, and the white square at 78% height.
func checkPattern(t *testing.T, img image.Image, width, height, tol int) {
	t.Helper()
	w, h := img.Bounds().Dx(), img.Bounds().Dy()
	if w != width || h != height {
		t.Fatalf("image bounds %dx%d, want %dx%d", w, h, width, height)
	}
	bars := [][3]int{{255, 0, 0}, {0, 255, 0}, {0, 0, 255}, {255, 255, 255}, {0, 0, 0}}
	y := h / 4
	for i, want := range bars {
		x := (2*i + 1) * w / 10
		r, g, b := chanVal(img, x, y)
		near(t, "bar R", r, want[0], tol)
		near(t, "bar G", g, want[1], tol)
		near(t, "bar B", b, want[2], tol)
	}
	y = h * 3 / 5
	lo, _, _ := chanVal(img, w/20, y)
	mid, _, _ := chanVal(img, w/2, y)
	hi, _, _ := chanVal(img, 19*w/20, y)
	if lo > 60 {
		t.Errorf("ramp left = %d, want dark", lo)
	}
	if mid < 75 || mid > 180 {
		t.Errorf("ramp mid = %d, want ~128", mid)
	}
	if hi < 200 {
		t.Errorf("ramp right = %d, want bright", hi)
	}
	r, g, b := chanVal(img, w/2, h*78/100)
	near(t, "square R", r, 255, tol)
	near(t, "square G", g, 255, tol)
	near(t, "square B", b, 255, tol)
}

func TestSSTVImageMartinM1(t *testing.T) {
	checkPattern(t, decodeFixture(t, "sstv_martin_m1"), 320, 256, 32)
}

func TestSSTVImageMartinM2(t *testing.T) {
	checkPattern(t, decodeFixture(t, "sstv_martin_m2"), 320, 256, 32)
}

func TestSSTVImageScottieS1(t *testing.T) {
	checkPattern(t, decodeFixture(t, "sstv_scottie_s1"), 320, 256, 32)
}

func TestSSTVImageScottieS2(t *testing.T) {
	checkPattern(t, decodeFixture(t, "sstv_scottie_s2"), 320, 256, 32)
}

func TestSSTVImageScottieDX(t *testing.T) {
	checkPattern(t, decodeFixture(t, "sstv_scottie_dx"), 320, 256, 32)
}

func TestSSTVImageRobot36(t *testing.T) {
	checkPattern(t, decodeFixture(t, "sstv_robot36"), 320, 240, 32)
}

// Impaired fixtures carry a receiver clock offset (+300 / -250 ppm) and
// ~15 dB SNR noise; per-line sync re-anchoring must still decode them.
func TestSSTVImageMartinM2Impaired(t *testing.T) {
	checkPattern(t, decodeFixture(t, "sstv_martin_m2_impaired"), 320, 256, 48)
}

func TestSSTVImageRobot36Impaired(t *testing.T) {
	checkPattern(t, decodeFixture(t, "sstv_robot36_impaired"), 320, 240, 48)
}

// TestSSTVDetectFixtures expects exactly one header with the right VIS
// code per fixture.
func TestSSTVDetectFixtures(t *testing.T) {
	for _, tc := range []struct {
		name string
		vis  int
		mode string
	}{
		{"sstv_martin_m1", 0x2C, "Martin M1"},
		{"sstv_martin_m2", 0x28, "Martin M2"},
		{"sstv_martin_m2_impaired", 0x28, "Martin M2"},
		{"sstv_scottie_s1", 0x3C, "Scottie S1"},
		{"sstv_scottie_s2", 0x38, "Scottie S2"},
		{"sstv_scottie_dx", 0x4C, "Scottie DX"},
		{"sstv_robot36", 0x08, "Robot 36"},
		{"sstv_robot36_impaired", 0x08, "Robot 36"},
	} {
		samples, rate := readSSTVFixture(t, tc.name)
		hits := SSTVDetect(samples, rate)
		if len(hits) != 1 {
			t.Errorf("%s: %d headers, want 1 (%v)", tc.name, len(hits), hits)
			continue
		}
		if hits[0].VIS != tc.vis || hits[0].Mode != tc.mode {
			t.Errorf("%s: VIS %#02x mode %q, want %#02x %q",
				tc.name, hits[0].VIS, hits[0].Mode, tc.vis, tc.mode)
		}
	}
}

// TestSSTVDetectNoFalsePositivesInImageData strips the header from each
// fixture; the swept video tones that remain must not produce a single
// false VIS header.
func TestSSTVDetectNoFalsePositivesInImageData(t *testing.T) {
	for _, name := range []string{
		"sstv_martin_m1", "sstv_martin_m2", "sstv_martin_m2_impaired",
		"sstv_scottie_s1", "sstv_robot36", "sstv_robot36_impaired",
	} {
		samples, rate := readSSTVFixture(t, name)
		hits := SSTVDetect(samples, rate)
		if len(hits) != 1 {
			t.Fatalf("%s: %d headers, want 1", name, len(hits))
		}
		start := int((hits[0].StartSec + 0.010 + 0.300 + 10*sstvBitLen) * float64(rate))
		if rest := SSTVDetect(samples[start:], rate); len(rest) != 0 {
			t.Errorf("%s: %d false VIS headers inside image data: %v", name, len(rest), rest)
		}
	}
}

// TestSSTVDetectRejectsHeaderWithoutImage: a valid header followed by
// silence has no line-sync cadence and must be rejected when audio
// continues.
func TestSSTVDetectRejectsHeaderWithoutImage(t *testing.T) {
	samples, rate := readSSTVFixture(t, "sstv_martin_m2")
	hits := SSTVDetect(samples, rate)
	if len(hits) != 1 {
		t.Fatalf("%d headers, want 1", len(hits))
	}
	cut := int((hits[0].StartSec + 0.010 + 0.300 + 10*sstvBitLen) * float64(rate))
	headerPlusSilence := append(samples[:cut:cut], make([]float64, 2*rate)...)
	if rest := SSTVDetect(headerPlusSilence, rate); len(rest) != 0 {
		t.Errorf("header without image accepted: %v", rest)
	}
}

// TestSSTVImageTruncated cuts the Martin M2 fixture shortly after the
// header; under 80% of the lines are present, so decoding must fail.
func TestSSTVImageTruncated(t *testing.T) {
	samples, rate := readSSTVFixture(t, "sstv_martin_m2")
	hits := SSTVDetect(samples, rate)
	if len(hits) != 1 {
		t.Fatalf("%d headers, want 1", len(hits))
	}
	spec := sstvModeSpecs[0x28]
	imageStart := hits[0].StartSec + 0.010 + 0.300 + 10*sstvBitLen
	cut := int((imageStart + 0.4*float64(spec.height)*spec.lineSec()) * float64(rate))
	if _, err := SSTVImage(samples[:cut], rate); err == nil {
		t.Fatal("truncated Martin M2 frame decoded without error")
	} else if !strings.Contains(err.Error(), "truncated") {
		t.Fatalf("error %q does not mention truncation", err)
	}
}

// TestSSTVImageHeaderOnly: the VIS reference fixture carries a header and
// a handful of lines, far under 80% of a frame.
func TestSSTVImageHeaderOnly(t *testing.T) {
	samples, rate, err := ReadWAV("../../../tests/data/ref_sstv.wav")
	if err != nil {
		t.Fatal(err)
	}
	if _, err := SSTVImage(samples, rate); err == nil {
		t.Fatal("header-only clip decoded without error")
	}
}

func TestSSTVImageRejectsShortClip(t *testing.T) {
	short := make([]float64, 22050)
	if _, err := SSTVImage(short, 22050); err == nil {
		t.Fatal("short clip without SSTV header accepted")
	}
}

// Sharp image edges splatter broadband energy at every transition, so
// the sync-cadence check must tolerate spurious short runs interleaved
// between the true syncs. A hard-edged bar pattern (the worst case:
// step transitions in every channel on every line) must still detect.
func TestSSTVDetectToleratesHardEdges(t *testing.T) {
	samples := sstvfixture.EncodeMartinM1(func(x, y int) (uint8, uint8, uint8) {
		if y < sstvfixture.Height/2 {
			switch x * 6 / sstvfixture.Width {
			case 0:
				return 255, 0, 0
			case 1:
				return 255, 255, 0
			case 2:
				return 0, 255, 0
			case 3:
				return 0, 255, 255
			case 4:
				return 0, 0, 255
			default:
				return 255, 0, 255
			}
		}
		return uint8(x * 255 / (sstvfixture.Width - 1)), uint8(y * 255 / (sstvfixture.Height - 1)), 128
	})
	hits := SSTVDetect(samples, sstvfixture.Rate)
	if len(hits) != 1 || hits[0].VIS != 0x2C {
		t.Fatalf("hard-edged frame: %+v, want one Martin M1 hit", hits)
	}
}
